<?php defined( 'ABSPATH' ) || exit; get_header(); ?>
<?php while ( have_posts() ) : the_post(); $project = 'sk_project' === get_post_type(); ?>
<article class="container article-layout"><header class="page-heading"><a class="text-link breadcrumb" href="<?php echo esc_url( skp_url( $project ? 'projects' : 'insights' ) ); ?>">← <?php echo esc_html( $project ? 'All projects' : 'All insights' ); ?></a><p class="eyebrow"><?php echo esc_html( $project ? 'PROJECT / FIELD NOTES' : 'FROM THE NOTEBOOK' ); ?></p><h1><?php echo esc_html( get_the_title() ); ?></h1><div class="article-meta"><?php if ( $project ) : $status = get_post_meta( get_the_ID(), 'sk_status', true ); if ( 'completed' === $status && ! trim( get_post_meta( get_the_ID(), 'sk_evidence', true ) ) ) { $status = 'in-progress'; } ?><span class="status"><i></i><?php echo esc_html( array( 'planned' => 'Planned', 'in-progress' => 'In Progress', 'completed' => 'Completed' )[ $status ] ?? 'Planned' ); ?></span><?php else : ?><span><?php echo esc_html( get_the_date( 'F j, Y' ) ); ?></span><span><?php printf( esc_html__( '%s min read', 'sidartha' ), esc_html( skp_reading_time( get_the_ID() ) ) ); ?></span><?php endif; ?><span><?php echo esc_html( skp_profile( 'name' ) ); ?></span></div></header>
<?php if ( has_post_thumbnail() ) : ?><figure class="article-cover"><?php the_post_thumbnail( 'large' ); ?></figure><?php endif; ?>
<div class="prose prose-large"><?php the_content(); wp_link_pages(); ?></div>
<?php if ( $project ) : ?><div class="project-links"><?php foreach ( array( 'sk_repository' => 'View source', 'sk_demo' => 'Visit demo' ) as $key => $label ) : $url = get_post_meta( get_the_ID(), $key, true ); if ( $url ) : ?><a class="button button-secondary" href="<?php echo esc_url( $url ); ?>"><?php echo esc_html( $label ); ?> <?php skp_icon( 'diagonal' ); ?></a><?php endif; endforeach; ?></div><?php else : ?><div class="article-categories"><?php the_category( ' ' ); ?></div><?php endif; ?>
</article><?php endwhile; skp_contact_band(); get_footer(); ?>
